def find_two_sum(numbers: list[int], target: int) -> list[int]:
    """Finds two numbers from a given list that add up to a target number."""

    num_dict = {}  # Dictionary to store visited elements and their indices.

    for index, num in enumerate(numbers):
        diff = target - num

        if diff in num_dict:
            return [num_dict[diff], index]

        num_dict[num] = index

    raise ValueError("No two sum solution")

